    ('classic-ankle-kids', 'Classic Ankle', 'KIDS', 'classic', 'ankle', 'Little Ones',
     'Plain ankle socks in bright, easy colours, for summer and for sport class.',
     '80% combed cotton / 18% polyester / 2% elastane', 'Soft combed cotton'),
    ('classic-knee-high-kids', 'School Knee-High', 'KIDS', 'classic', 'knee-high', 'Back to School',
